export const clamp=(t,o,r)=>{let e=t;return t<o?e=o:t>r&&(e=r),e};export const mod=(t,o)=>(t%o+o)%o;export const bytesToString=t=>{if(t<1e3)return`${t.toFixed(0)} B`;const o=t/1e3;if(o<100)return`${o.toFixed(1)} kB`;if(o<1e3)return`${o.toFixed(0)} kB`;const r=o/1e3;return r<100?`${r.toFixed(1)} MB`:`${r.toFixed(0)} MB`};export const toFixedIfFloating=t=>{if(!t||Number.isNaN(Number(t)))return t;const o=Number(t);return o%1?o.toFixed(3):String(o)};export const floor=(t,o=0)=>{const r=Math.pow(10,o);return Math.floor(t*r)/r};export const greatestCommonDivisor=(t,o)=>{for(t=Math.round(t),o=Math.round(o);0!==o;){const r=o;o=t%o,t=r}return t};const commonRatios=new Map([["8∶5","16∶10"]]);export const aspectRatio=(t,o)=>{const r=greatestCommonDivisor(t,o);0!==r&&(t/=r,o/=r);const e=`${t}∶${o}`;return commonRatios.get(e)||e};export const withThousandsSeparator=function(t){let o=String(t);const r=/(\d+)(\d{3})/;for(;o.match(r);)o=o.replace(r,"$1 $2");return o};